 "info": [
  {
   "field": "identity_values",
   "about": "Any 2 of date of birth, email, phone number and address. These are checked against the records.",
   "from": "customer",
   "ask": "To verify your identity, could you please give me two of the following: your date of birth, email address, phone number or home address?",
   "may_hold_back": true
  },
  {
   "field": "disputed_transaction",
   "about": "The merchant and the approximate amount or date. These are used to find the transaction_id and purchase_date in the card transaction records.",
   "from": "customer",
   "ask": "Which charge would you like to dispute? Please tell me the merchant, and the approximate amount and date if you know them.",
   "may_hold_back": false
  },
  {
   "field": "disputed_transactions_selection",
   "about": "When the customer names only a merchant, or says several charges are wrong: which of the listed transactions they want to dispute, and what is wrong with each one",
   "from": "customer",
   "ask": "Here are the recent charges from this merchant on your card. Which of them do you want to dispute, and what is wrong with each one?",
   "may_hold_back": true
  },
  {
   "field": "cards_involved",
   "about": "When the customer disputes charges on more than one card: which card each disputed charge is on. Confirm this against the transaction records.",
   "from": "customer",
   "ask": "Which of your cards is each of these charges on?",
   "may_hold_back": false
  },
  {
   "field": "dispute_reason",
   "about": "One of unauthorized_fraudulent_charge, duplicate_charge, incorrect_amount, goods_services_not_received, goods_services_not_as_described, canceled_subscription_still_charging or refund_never_processed. Getting something different from what was paid for (for example, a different or cheaper room or item) is goods_services_not_as_described. A charge repeated a second time is duplicate_charge.",
   "from": "customer",
   "ask": "Which of these best describes the problem: an unauthorized or fraudulent charge, a duplicate charge, an incorrect amount, goods or services not received, goods or services not as described, a cancelled subscription that is still charging, or a refund that was never processed?",
   "may_hold_back": true
  },
  {
   "field": "contacted_merchant",
   "about": "Whether the customer tried to resolve the issue with the merchant first (true or false). Ask for each transaction, including fraud disputes.",
   "from": "customer",
   "ask": "Did you try to resolve this with the merchant first?",
   "may_hold_back": true
  },
  {
   "field": "issue_noticed_date",
   "about": "The date the customer noticed the issue, as MM/DD/YYYY. If the customer says 'today', get the date from get_current_time. Never guess a date.",
   "from": "customer",
   "ask": "When did you notice the issue?",
   "may_hold_back": true
  },
  {
   "field": "resolution_requested",
   "about": "One of full_refund, partial_refund (needs partial_refund_amount) or reversal_of_charge",
   "from": "customer",
   "ask": "Which resolution would you like: a full refund, a partial refund (and how much), or a reversal of the charge?",
   "may_hold_back": true
  },
  {
   "field": "partial_refund_amount",
   "about": "The dollar amount, needed only if resolution_requested is partial_refund",
   "from": "customer",
   "ask": "How much would you like refunded?",
   "may_hold_back": true
  },
  {
   "field": "card_action",
   "about": "keep_active, or cancel_and_reissue if the customer wants the card replaced. Ask once per card when several cards are involved.",
   "from": "customer",
   "ask": "Would you like to keep your card active, or cancel it and have a replacement issued?",
   "may_hold_back": true
  },
  {
   "field": "card_last_4_digits",
   "about": "The last 4 digits of the card used for the disputed transaction. Ask once per card when several cards are involved.",
   "from": "customer",
   "ask": "What are the last 4 digits of the card used for this charge?",
   "may_hold_back": true
  },
  {
   "field": "credit_card_account_id",
   "about": "The credit card account ID. It is needed for get_card_last_4_digits and get_pending_replacement_orders_5765. It shows which card holds the transaction and that card's tier, and it is used to read the account's open date.",
   "from": "records",
   "ask": "",
   "may_hold_back": false
  },
  {
   "field": "replacement_details",
   "about": "Needed only for cancel_and_reissue with a replacement order: the confirmed shipping address (the address on file, or an alternate such as a work address, with suite or unit), the replacement reason (fraud_suspected, lost, stolen, damaged, expired or other) and the shipping speed (standard, or expedited with any tier fee)",
   "from": "customer",
   "ask": "Where should we ship the replacement card, what is the reason for the replacement, and would you like standard or expedited shipping?",
   "may_hold_back": true
  },
  {
   "field": "provisional_credit_priority",
   "about": "When the customer files several disputes: which ones they most want handled first, for example the ones hurting their cash flow most. Use it to order the filings.",
   "from": "customer",
   "ask": "Which of these disputes are most important for you to have handled first?",
   "may_hold_back": true
  },
  {
   "field": "other_requests",
   "about": "Any other request the customer raised in the same conversation (for example a credit limit increase), to handle after the dispute in the order the customer gave",
   "from": "customer",
   "ask": "Is there anything else I can help you with today?",
   "may_hold_back": false
  }
 ],
 "steps": [
  {
   "id": "lookup_user",
   "by": "model",
   "do": "Greet the customer, acknowledge every request they named, and ask for identifying details. Look them up with get_user_information_by_email if they give an email, get_user_information_by_name (case-sensitive) if they give a name, or get_user_information_by_id if they give a user id.",
   "call": "get_user_information_by_email",
   "args": {
    "email": "the email the customer gave"
   },
   "lookup": [],
   "after": [],
   "if": null,
   "quote": "To verify the identity of the user, call the appropriate read tools, and ensure that they are able to give correctly any 2 out of the following values: date of birth, email, phone number, address.",
   "doc": "policy"
  },
  {
   "id": "verify",
   "by": "model",
   "do": "Confirm that at least 2 of date of birth, email, phone and address match the record from lookup_user. Share no account information before they match. If they do not match, ask again. If verification still fails, stop.",
   "call": null,
   "args": {},
   "lookup": [
    "lookup_user"
   ],
   "after": [
    "lookup_user"
   ],
   "if": null,
   "quote": "Knowing full name or userID is not enough to verify.",
   "doc": "policy"
  },
  {
   "id": "get_time",
   "by": "harness",
   "do": "Get the current time. Use it for the verification log, for any date the customer gives as 'today', and to work out account age and purchase age.",
   "call": "get_current_time",
   "args": {},
   "lookup": [],
   "after": [
    "verify"
   ],
   "if": null,
   "quote": "If you need the current time, always use the get_current_time() tool.",
   "doc": "policy"
  },
  {
   "id": "log_verification",
   "by": "harness",
   "do": "Log the verification.",
   "call": "log_verification",
   "args": {
    "name": "the verified user's name",
    "user_id": "the verified user id",
    "address": "address on record",
    "email": "email on record",
    "phone_number": "phone on record",
    "date_of_birth": "date of birth on record",
    "time_verified": "the current time"
   },
   "lookup": [
    "verify"
   ],
   "after": [
    "get_time"
   ],
   "if": "2 or more values matched",
   "quote": "After verification, you must call the verification logging tool to properly log the information into the verification records.",
   "doc": "policy"
  },
  {
   "id": "get_accounts",
   "by": "harness",
   "do": "Get the user's credit card accounts. Note each one's card type (tier), account id and open date.",
   "call": "get_credit_card_accounts_by_user",
   "args": {
    "user_id": "the verified user id"
   },
   "lookup": [],
   "after": [
    "log_verification"
   ],
   "if": null,
   "quote": "1. Account Standing: The customer's credit card account has been open for at least 60 days",
   "doc": "doc_credit_cards_credit_cards_(general)_015"
  },
  {
   "id": "get_transactions",
   "by": "harness",
   "do": "Get the user's card transactions and find each disputed one by merchant and amount. This gives its transaction_id and purchase_date.",
   "call": "get_credit_card_transactions_by_user",
   "args": {
    "user_id": "the verified user id"
   },
   "lookup": [],
   "after": [
    "log_verification"
   ],
   "if": null,
   "quote": "1. transaction_id (string) - ID of the transaction being disputed. ",
   "doc": "doc_credit_cards_credit_cards_(general)_014"
  },
  {
   "id": "list_merchant_transactions",
   "by": "model",
   "do": "List the transactions in get_transactions for the merchant the customer named, with the date and amount of each. Ask which ones they want to dispute and what is wrong with each. Do not guess which charges are disputed.",
   "call": null,
   "args": {},
   "lookup": [
    "get_transactions",
    "get_accounts"
   ],
   "after": [
    "get_transactions",
    "get_accounts"
   ],
   "if": "the customer names only a merchant or says several charges are wrong, without giving the exact date and amount of each",
   "quote": "Please have your account information ready, along with any details about the transaction in question such as the purchase date, merchant name, and amount.",
   "doc": "doc_credit_cards_credit_cards_(general)_018"
  },
  {
   "id": "identify_transaction",
   "by": "model",
   "do": "Match the customer's merchant, approximate amount and date to exactly one transaction in get_transactions, and confirm it with the customer. From the record, take the transaction_id, the exact amount, the purchase date (MM/DD/YYYY) and the card account it was made on. If nothing matches, ask for more detail. If it still cannot be found, explain that the dispute cannot be filed without the transaction, and stop.",
   "call": null,
   "args": {},
   "lookup": [
    "get_transactions",
    "get_accounts"
   ],
   "after": [
    "get_transactions",
    "get_accounts"
   ],
   "if": null,
   "quote": "10. purchase_date (string, format MM/DD/YYYY) - The date in which the disputed transaction occurred.",
   "doc": "doc_credit_cards_credit_cards_(general)_014"
