   "doc": "doc_credit_cards_credit_cards_(general)_014"
  },
  {
   "id": "repeat_per_transaction",
   "by": "model",
   "do": "When the customer disputes more than one transaction, handle each one separately: identify_transaction, ask_reason, ask_merchant, ask_noticed, ask_resolution and decide_provisional, then one file_dispute call per transaction_id. Each dispute gets its own reason, merchant-contact answer and provisional credit decision. Use the same card_action for every dispute on the same card.",
   "call": null,
   "args": {},
   "lookup": [
    "identify_transaction",
    "list_merchant_transactions"
   ],
   "after": [
